// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

contract Owner{
    address owner;
    uint nombre;

    constructor(){
        owner = msg.sender;
    }

    function setNombre(uint _nombre) public {
        require(msg.sender == owner, "Vous n'etes pas le Proprietaire");
        nombre = _nombre;
    } 

    function getNombre() public view returns(uint){
        require(msg.sender == owner, "Vous n'etes pas le Proprietaire");
        return nombre;
    }
}

